export function assertLocalToolScope(calls){
 for(const call of calls){const args=JSON.parse(call.arguments),file=typeof args.filePath==='string'?args.filePath.replaceAll('\\','/'):'';const relative=file.startsWith('C:/RSTask/')?file.slice('C:/RSTask/'.length):file;
  if(call.name==='read'){if(!['backend-limit.mjs','backend-limit.test.mjs'].includes(relative))throw Error('local-tool-read-out-of-scope');}
  else if(['edit','write'].includes(call.name)){if(relative!=='backend-limit.mjs')throw Error('local-tool-write-out-of-scope');}
  else throw Error('local-tool-not-allowed');
 }
 return calls;
}

