import test from 'node:test';import assert from 'node:assert/strict';import {assertLocalToolScope} from './backend-limit.mjs';
const c=(name,filePath)=>({name,arguments:JSON.stringify({filePath})});
test('canonical source',()=>assertLocalToolScope([c('edit','C:/RSTask/backend-limit.mjs')]));
test('Windows prefix equivalence',()=>assertLocalToolScope([c('edit','c:/RSTask/backend-limit.mjs'),c('edit','C:/RSTASK/backend-limit.mjs'),c('read','c:/rstask/backend-limit.test.mjs')]));
test('protected tests read only',()=>{assertLocalToolScope([c('read','backend-limit.test.mjs')]);for(const p of ['backend-limit.test.mjs','c:/rstask/backend-limit.test.mjs'])assert.throws(()=>assertLocalToolScope([c('write',p)]),/scope/);});
test('traversal denied',()=>{for(const p of ['../backend-limit.mjs','C:/RSTask/sub/../backend-limit.mjs'])assert.throws(()=>assertLocalToolScope([c('edit',p)]),/scope/);});
test('external and lookalike directories denied',()=>{for(const p of ['C:/Other/backend-limit.mjs','C:/RSTask-other/backend-limit.mjs'])assert.throws(()=>assertLocalToolScope([c('read',p)]),/scope/);});
test('shell unavailable',()=>assert.throws(()=>assertLocalToolScope([c('bash','backend-limit.mjs')]),/not-allowed/));
